content.css:
.hierarchy-selector {
  box-sizing: border-box;
  display: flex;
  align-items: stretch;
  gap: 12px;
  width: 100%;
  height: 100%;
  padding: 12px;
  overflow: auto;
  font-family: Arial, sans-serif;
}
.hierarchy-level {
  box-sizing: border-box;
  display: flex;
  min-width: 160px;
  flex: 1 1 0;
  flex-direction: column;
  gap: 6px;
}
.hierarchy-level__label {
  overflow: hidden;
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 600;
  line-height: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hierarchy-level__values {
  box-sizing: border-box;
  display: flex;
  min-height: 0;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 4px;
  padding: 4px;
  overflow-y: auto;
  border: 1px solid #d1d1d1;
  border-radius: 4px;
}
.hierarchy-level__value {
  box-sizing: border-box;
  width: 100%;
  min-height: 32px;
  padding: 6px 10px;
  overflow: hidden;
  border: 1px solid transparent;
  border-radius: 4px;
  background: transparent;
  color: #242424;
  font: inherit;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}
.hierarchy-level__value:hover {
  background: #f0f0f0;
}
.hierarchy-level__value:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 1px;
}
.hierarchy-level__empty {
  padding: 8px;
  font-size: 12px;
  font-style: italic;
}
.hierarchy-selector__landing-page {
  box-sizing: border-box;
  display: flex;
  width: 100%;
  height: 100%;
  min-height: 100px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  text-align: center;
}
.hierarchy-selector__landing-heading {
  margin-bottom: 6px;
  font-size: 16px;
  font-weight: 600;
  line-height: 22px;
}
.hierarchy-selector__landing-text {
  max-width: 300px;
  font-size: 12px;
  line-height: 18px;
}
